-- ============================================================
-- Migration 003: Home Sections Setup
-- Creates the home_sections table to manage ordering, type, and status
-- of all components on desktop and mobile homepages.
-- ============================================================

CREATE TABLE IF NOT EXISTS `home_sections` (
  `id`                    int(11)       NOT NULL AUTO_INCREMENT,
  `page_target`           enum('desktop','mobile') NOT NULL,
  `section_type`          varchar(50)   NOT NULL COMMENT 'slider | banner | product_carousel | category_mosaic | compact_grid | mobile_list | featured_grid | brand_directory | bulk_widget | gift_finder',
  `section_key`           varchar(80)   NOT NULL,
  `label`                 varchar(120)  NOT NULL,
  `columns_per_row`       tinyint(1)    NOT NULL DEFAULT 1,
  `is_slider`             tinyint(1)    NOT NULL DEFAULT 0,
  `api_action`            varchar(80)   DEFAULT NULL,
  `product_limit`         int(11)       DEFAULT 10,
  `badge_text`            varchar(50)   DEFAULT NULL,
  `background_image_url`  varchar(255)  DEFAULT NULL,
  `display_order`         int(11)       NOT NULL DEFAULT 0,
  `status`                enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at`            timestamp     NOT NULL DEFAULT current_timestamp(),
  `updated_at`            timestamp     NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_target_key` (`page_target`, `section_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

